      "sql": "<h1>Structured Query Language</h1>\n<p>Contents: data definition, data modification, query, view, authorization, assertion</p>\n<h2>1. Data Definition</h2>\n<h3>CREATE TABLE</h3>\n<pre><code class=\"language-sql\">CREATE TABLE Branch\n(\n    branch_id VARCHAR(15),\n    name VARCHAR(30) NOT NULL,\n    asset INT UNSIGNED NOT NULL,\n    PRIMARY KEY (branch_id)\n);</code></pre>\n<ul>\n<li>name, type</li>\n<li>constraint</li>\n</ul>\n<pre><code class=\"language-sql\">CREATE TABLE Owner\n(\n    account_id VARCHAR(15),\n    customer_id VARCHAR(15),\n    PRIMARY KEY (account_id, customer_id),\n    FOREIGN KEY (account_id) REFERENCES Account(account_id),\n    FOREIGN KEY (customer_id) REFERENCES Customer(customer_id)\n);</code></pre>\n<h3>DROP TABLE</h3>\n<pre><code class=\"language-sql\">DROP TABLE Branch;</code></pre>\n<h3>ALTER TABLE</h3>\n<p>ADD/DROP column</p>\n<pre><code class=\"language-sql\">ALTER TABLE Branch ADD branch_phone VARCHAR(20);\nALTER TABLE Branch DROP branch_phone;</code></pre>\n<p>ADD/DROP constraints</p>\n<pre><code class=\"language-sql\">ALTER TABLE Branch ADD PRIMARY KEY (branch_id);\nALTER TABLE Owner ADD FOREIGN KEY (customer_id)\nREFERENCES Customer (customer_id);</code></pre>\n<h2>2. Data Modification</h2>\n<h3>INSERT</h3>\n<pre><code class=\"language-sql\">INSERT INTO Branch VALUES ('B1', 'Central', 1);\nINSERT INTO Branch VALUES ('B1', ......)\n                          ('B2', ......);</code></pre>\n<pre><code class=\"language-sql\">LOAD DATA LOCAL INFILE 'text.txt'\nINTO TABLE Branch\nFIELDS TERMINATED BY ';'\nLINES TERMINATED BY '\\n';</code></pre>\n<h3>DELETE</h3>\n<pre><code class=\"language-sql\">DELETE FROM Branch;\nDELETE FROM Branch WHERE name = 'CENTRAL';</code></pre>\n<h3>UPDATE</h3>\n<pre><code class=\"language-sql\">UPDATE Branch\nSET asset = 0\nWHERE branch_id = 'B1';</code></pre>\n<pre><code class=\"language-sql\">UPDATE Account\nSET balance = balance * 1.06\nWHERE balance &gt;500;</code></pre>\n<pre><code class=\"language-sql\">UPDATE Account\nSET balance = CASE\nWHEN balance &lt;500 THEN balance *1.05\nELSE balance *1.06\nEND;</code></pre>\n<h2>3. Query</h2>\n<pre><code class=\"language-sql\">SELECT name FROM Customer;\nSELECT * FROM Customer;\nSELECT loan_id, amount /7.8 FROM Loan;</code></pre>\n<p>Cartesian product</p>\n<pre><code class=\"language-sql\">SELECT * FROM Customer, Borrower;</code></pre>\n<p>Where</p>\n<pre><code class=\"language-sql\">SELECT Borrower.loan_id, Customer.name\nFROM Customer, Borrower\nWHERE Customer.customer_id = Borrower.customer_id;</code></pre>\n<pre><code class=\"language-sql\">SELECT loan_id\nFROM Loan\nWHERE branch_id = 'B1' AND amount &gt;1200;</code></pre>\n<pre><code class=\"language-sql\">SELECT DISTINCT Branch.name\nFROM Branch , Loan\nWHERE Branch.branch_id = Loan.branch_id;</code></pre>\n<p>AS</p>\n<pre><code class=\"language-sql\">SELECT DISTINCT Branch.name AS 'Branch name'\n......</code></pre>\n<p>Rename</p>\n<pre><code class=\"language-sql\">SELECT DISTINCT B.name AS 'Branch name'\nFROM Branch B, Loan L\nWHERE B.branch_id = L.branch_id;</code></pre>\n<p>Pattern:</p>\n<ul>\n<li><code>%</code> : matches any substring</li>\n<li><code>_</code> : matches any character</li>\n</ul>\n<pre><code class=\"language-sql\">SELECT name\nFROM Customer\nWHERE address LIKE '%3n%';</code></pre>\n<h3>ORDER BY</h3>\n<p><code>DESC</code> descending <code>ASC</code> ascending ← default</p>\n<pre><code class=\"language-sql\">SELECT name\nFROM Customer\nWHERE ORDER BY name ASC;</code></pre>\n<pre><code class=\"language-sql\">SELECT *\nFROM Loan\nORDER BY branch_id ASC , amount DESC;</code></pre>\n<h3>Aggregation</h3>\n<p>AVG, SUM, MIN, MAX, COUNT</p>\n<pre><code class=\"language-sql\">SELECT AVG(balance)\nFROM Account\nWHERE branch_id = 'B2';</code></pre>\n<pre><code class=\"language-sql\">SELECT branch_id, AVG(balance)\nFROM Account\nGROUP BY branch_id;</code></pre>\n<pre><code class=\"language-sql\">SELECT branch_id, AVG(balance)\nFROM Account\nGROUP BY branch_id\nHAVING AVG(balance) &gt;= 650;</code></pre>\n<h3>Nested Query</h3>\n<pre><code class=\"language-sql\">WHERE column IN ()\nWHERE column ? ALL()\nWHERE column ? SOME()\nWHERE EXISTS ()</code></pre>\n<pre><code class=\"language-sql\">SELECT E.name\nFROM Employee E\nWHERE E.employee_id IN (\n    SELECT W.employee_id\n    FROM Works_in W\n    WHERE W.department_id =1\n);</code></pre>\n<pre><code class=\"language-sql\">SELECT D.name\nFROM Department D\nWHERE D.budget &gt; ALL (\n    SELECT D2.budget\n    FROM Department D2\n    WHERE D2.department_id IN (\n        SELECT W.department_id\n        FROM Works_in W\n        WHERE W.employee_id =4\n    )\n);</code></pre>\n<pre><code class=\"language-sql\">SELECT D.name\nFROM Department D\nWHERE D.budget &gt; SOME (\n    SELECT D2.budget\n    FROM Department D2\n    WHERE D2.department_id IN (\n        SELECT W.department_id\n        FROM Works_in W\n        WHERE W.employee_id =2\n    )\n);</code></pre>\n<pre><code class=\"language-sql\">SELECT E.name\nFROM Employee E\nWHERE EXISTS (\n    SELECT *\n    FROM Works_in W\n    WHERE E.employee_id = W.employee_id AND\n    W.department_id =1\n);</code></pre>\n<h3>Set operation: UNION, EXCEPT, INTERSECT</h3>\n<pre><code class=\"language-sql\">SELECT E.name\nFROM Employee E, Works_in W\nWHERE E.employee_id = W.employee_id AND W.department_id =1\n\nUNION / INTERSECT\n\nSELECT E.name\nFROM Employee E, Works_in W\nWHERE E.employee_id = W.employee_id AND W.department_id =3\n</code></pre>\n<pre><code class=\"language-sql\">...... =1 EXCEPT ...... =3</code></pre>\n<h3>Join</h3>\n<p>LEFT OUTER JOIN/ RIGHT OUTER JOIN Left table all rows show; Right table fill null Two table not match → null</p>\n<pre><code class=\"language-sql\">SELECT *\nFROM Employee E, Department D\nWHERE E.department_id = D.department_id</code></pre>\n<pre><code class=\"language-sql\">SELECT *\nFROM Employee E\nINNER JOIN Department D\nON E.department_id = D.department_id;</code></pre>\n<h3>NULL</h3>\n<pre><code class=\"language-sql\">SELECT name\nFROM Employee\nWHERE salary IS NULL;</code></pre>\n<ul>\n<li>SUM, AVG, MIN, MAX, COUNT(expression) ignore NULL inputs</li>\n<li>COUNT(*) count rows and does not ignore</li>\n<li>null: Value not exist</li>\n<li>UNKNOWN: TRUE, FALSE, UNKNOWN</li>\n<li>arithmetic expression involving null is null</li>\n<li>null +5 =null</li>\n<li>ordinary comparison = < > with null evaluate to UNKNOWN</li>\n<li>5 < null, null = null return UNKNOWN</li>\n<li>IS UNKNOWN</li>\n<li>for WHERE, HAVING, predict false if it evaluates to UNKNOWN.</li>\n</ul>\n<h2>4. VIEW</h2>\n<pre><code class=\"language-sql\">CREATE VIEW Employee_hide_salary AS (\n    SELECT employee_id , name\n    FROM Employee\n);</code></pre>\n<pre><code class=\"language-sql\">CREATE VIEW Dept_size(name, num_of_employee) AS (\n    SELECT D.name, COUNT(*)\n    FROM Department D, Works_in W\n    WHERE D.department_id = W.department_id\n    GROUP BY W.department_id\n);</code></pre>\n<h2>5. Authorization</h2>\n<p>table/view, user/role</p>\n<pre><code class=\"language-sql\">GRANT SELECT ON Department TO Johnson, Brown;\nGRANT UPDATE(budget) ON Department TO Johnson;\nGRANT UPDATE (budget) ON Department TO manager;\n(REVOKE)</code></pre>\n<pre><code class=\"language-sql\">CREATE Role manager;\nGRANT manager TO Brown;\nCREATE USER Johnson IDENTIFIED BY 'password'</code></pre>\n<h2>6. Assertion</h2>\n<pre><code class=\"language-sql\">CREATE ASSERTION EmpsNoLessThanDepts\nCHECK (\n    (SELECT COUNT(*) FROM Department) &lt;=\n    (SELECT COUNT(*) FROM Employee)\n);</code></pre>"
